/** Effects grouped by their `category`, preserving order. */
export function effectsByCategory(effects = EFFECTS) {
  const groups = new Map();
  for (const e of effects) {
    if (!groups.has(e.category)) groups.set(e.category, []);
    groups.get(e.category).push(e);
  }
  return groups;
}

/** The CDP programs an effect needs loaded (spectral effects also need pvoc;
 *  derive-based effects also need the programs listed in `effect.needs`). */
export function programsFor(effect) {
  const base = effect.domain === 'spectral' ? ['pvoc', effect.program] : [effect.program];
  return effect.needs ? [...new Set([...base, ...effect.needs])] : base;
}

/**
 * Derive a pitch breakpoint file (time/frequency pairs) for the input by running
 * CDP's pitch tracker (`pvoc anal` → `repitch getpitch`). Falls back to a constant
 * pitch from the `pitch` parameter when the source isn't clearly pitched (a pure
 * tone or noise yields no breakpoints) — so the effect always has usable data.
 */

// Deterministic vertex layout for crystal.rotate: a seeded LCG (no
// Math.random) so the same settings always generate the same crystal.
function crystalData(v) {
  let s = (Number(v.seed) * 2654435761) >>> 0;
  const rnd = () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296; };
  const r = Number(v.radius);
  const lines = [];
  for (let n = 0; n < v.verts; n++) {
    let x, y, z;
    do { x = (rnd() * 2 - 1) * r; y = (rnd() * 2 - 1) * r; z = (rnd() * 2 - 1) * r; }
    while (x * x + y * y + z * z >= r * r);
    lines.push(`${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}`);
  }
  lines.push(`0 0`);
  lines.push(`${v.attack} 1`);
  lines.push(`${(Number(v.attack) + Number(v.decay)).toFixed(4)} 0`);
  return lines.join('\n') + '\n';
}

// Fragment envelope table for fracture.fracture: one line — TIME 0 plus 7
// time/level pairs rising to 1 at the peak position and falling back to 0.
function fractureData(v) {
  const p = Number(v.peak);
  const pts = [[0, 0], [p / 2, 0.5], [p, 1],
    [p + (1 - p) * 0.25, 0.65], [p + (1 - p) * 0.5, 0.4], [p + (1 - p) * 0.75, 0.18], [1, 0]];
  return `0 ${pts.map(([t, l]) => `${t.toFixed(4)} ${l}`).join(' ')}\n`;
}

async function derivePitch(cdp, monoWav, values) {
  try {
    const ana = await analyse(cdp, monoWav);
    const r = await cdp.run('repitch', ['getpitch', '2', '/in.ana', '/o.wav', '/p.txt'],
      { inputs: { '/in.ana': ana }, outputs: ['/p.txt'] });
    const t = r.outputs['/p.txt'];
    if (t && t.length) {
      const lines = new TextDecoder().decode(t).trim().split(/\r?\n/).filter(Boolean);
      if (lines.length >= 2) return t; // a usable, data-reduced pitch contour
    }
  } catch { /* fall through to the constant-pitch fallback */ }
  // Fallback: a constant pitch spanning the source (psow requires the breakpoint
  // file's time range to match the input's duration).
  const d = decodeAudio(monoWav);
  const dur = (d.length / d.sampleRate).toFixed(6);
  const hz = values.pitch || 220;
  return `0 ${hz}\n${dur} ${hz}\n`;
}

/**
 * The range a parameter may actually take, given what its siblings are set to.
 *
 * Some CDP constraints couple parameters and a fixed min/max cannot express
 * them: a spatialisation centre must name one of the output channels, `isolate`
 * needs its minimum segment longer than twice the splice, `distort omit` needs
 * A below B. Declaring the full span leaves the UI offering values the program
 * rejects — which is exactly how a bad value reaches CDP.
 *
 * A parameter may therefore carry `minOf`/`maxOf`: each a function of the other
 * parameter values, returning the bound implied by them. The result is
 * intersected with the static `min`/`max`, which remain the absolute limits, so
 * a parameter without them behaves exactly as before.
 *
 * `opts.unlocked` widens the static span to the program's own limits for a
 * consumer that has chosen to leave the curated range (see `hardMin`/`hardMax`
 * on Param). The sibling bounds are deliberately still applied: `min`/`max` are
 * taste, but `minOf`/`maxOf` encode constraints CDP genuinely rejects, so
 * unlocking must not reopen them.
 *
 * @param {object} p       a parameter descriptor
 * @param {Record<string, number|string>} [values]  the sibling values
 * @param {{unlocked?: boolean}} [opts]
 * @returns {{min:number, max:number}}
 */
export function paramRange(p, values = {}, opts = {}) {
  // Only fall back to the curated bound where no engine limit has been recorded;
  // the caller widens further from there if it wants to (see paramRow).
  let min = opts.unlocked && p.hardMin != null ? p.hardMin : p.min;
  let max = opts.unlocked && p.hardMax != null ? p.hardMax : p.max;
  const bound = (fn) => { const v = Number(fn(values)); return Number.isFinite(v) ? v : null; };
  if (typeof p.minOf === 'function') { const v = bound(p.minOf); if (v != null) min = Math.max(min, v); }
  if (typeof p.maxOf === 'function') { const v = bound(p.maxOf); if (v != null) max = Math.min(max, v); }
  // Over-constrained (e.g. splice turned right up): collapse to a single usable
  // value rather than handing back an inverted range.
  if (max < min) max = min;
  return { min, max };
}

/**
 * Build the concrete argument list from an effect template and parameter values.
 * '$SR' tokens (used by generators) resolve to `sampleRate`; effects have none.
 */
export function buildArgs(effect, values = {}, sampleRate = 44100) {
  return effect.args.map((a) => {
    if (a === '$IN' || a === '$OUT') return a;
    if (a === '$SR') return String(sampleRate);
    if (a && typeof a === 'object' && a.p != null) {
      const v = values[a.p];
      const s = String(v != null ? v : paramDefault(effect, a.p));
      return a.flag ? a.flag + s : s;
    }
    return a;
  });
}

function paramDefault(effect, name) {
  const p = (effect.params || []).find((x) => x.name === name);
  return p ? p.default : '';
}

/**
 * Apply a catalog effect to a WAV byte array and return the processed WAV.
 * Handles spectral (pvoc) wrapping and mono-only programs (per-channel split),
 * preserving channel count for stereo/multichannel sources.
 *
 * @param {import('./index.js').CDP} cdp
 * @param {object} effect  an entry from EFFECTS
 * @param {Record<string,number>} values  current parameter values
 * @param {Uint8Array} srcWav
 * @returns {Promise<Uint8Array>}
 */
export async function applyEffect(cdp, effect, values, srcWav, extra = {}) {
  // Effects with a custom multi-step chain (e.g. pitch-data autotune) own their
  // whole processing path. (Breakpoint envelopes aren't threaded through these.)
  if (effect.pipeline) return effect.pipeline(cdp, srcWav, values);

  // Breakpoint envelopes: any parameter can be supplied as a time-varying
  // envelope instead of a constant, via `extra.brk = { paramName: "t v\n..." }`.
  // Each becomes a /brk_<name>.brk file staged into MEMFS, and the parameter's
  // value is replaced by that path so CDP reads it as a breakpoint table.
  const brk = extra.brk || {};
  const brkInputs = {};
  const vals = { ...values };
  for (const name of Object.keys(brk)) {
    if (brk[name] == null || brk[name] === '') continue;
    const path = `/brk_${name}.brk`;
    brkInputs[path] = typeof brk[name] === 'string' ? new TextEncoder().encode(brk[name]) : brk[name];
    vals[name] = path; // buildArgs emits the path (with the flag prefix if the param is flagged)
  }

  const args = buildArgs(effect, vals);
  // Effects that read a text data file either generate it from the parameters
  // (`data`, referenced as '$DATA') or derive it from the input by running CDP
  // programs (`derive`, e.g. pitch extraction). We stage the result into MEMFS.
  const staticData = effect.data ? effect.data(vals) : undefined;

  // Mixfile chain (multimix/newmix, panorama): stage several inputs, run a
  // *build* program that writes a CDP mixfile describing them, then a *render*
  // program that turns that mixfile into one multichannel WAV. The full input
  // list is [srcWav, ...extra.inputs]; templates use '$INS' (the input paths,
  // spread inline), '$MIX' (the mixfile) and '$OUT'.
  if (effect.mixChain) {
    const mc = effect.mixChain;
    const rate = decodeAudio(srcWav).sampleRate;
    const wavs = [srcWav, ...(extra.inputs || [])]
      .map((w) => conformChannels(conformRate(w, rate), mc.inChannels || 'mono'));
    const inPaths = wavs.map((_, i) => `/in${i + 1}.wav`);
    const inputs = {};
    wavs.forEach((w, i) => { inputs[inPaths[i]] = w; });
    const mixPath = `/mix.${mc.ext || 'mmx'}`;
    const expand = (tpl) => tpl.flatMap((a) =>
      a === '$INS' ? inPaths
        : a === '$MIX' ? [mixPath]
          : a === '$OUT' ? ['/out.wav']
            : (a && typeof a === 'object' && a.p != null)
              ? [(a.flag || '') + String(vals[a.p] != null ? vals[a.p] : paramDefault(effect, a.p))]
              : [a]);
    const b = await cdp.run(mc.buildProgram, expand(mc.build), { inputs, outputs: [mixPath] });
    const mix = b.outputs[mixPath];
    if (!mix) throw new Error(`${mc.buildProgram} produced no mixfile (exit ${b.exitCode}).\n${b.stderr || b.stdout}`.trim());
    const r = await cdp.run(mc.renderProgram, expand(mc.render), { inputs: { [mixPath]: mix, ...inputs }, outputs: ['/out.wav'] });
    const out = r.outputs['/out.wav'];
    if (!out) throw new Error(`${mc.renderProgram} produced no output (exit ${r.exitCode}).\n${r.stderr || r.stdout}`.trim());
    return out;
  }

  // Variadic-input programs (rejoin, ...) take several soundfiles → one output.
  // The full input list is [srcWav, ...extra.inputs]; '$INS' expands to their
  // paths spread inline, '$OUT' is the single output.
  if (effect.variadicInputs) {
    const rate = decodeAudio(srcWav).sampleRate;
    const want = effect.input || null;
    const wavs = [srcWav, ...(extra.inputs || [])]
      .map((w) => { const r = conformRate(w, rate); return want ? conformChannels(r, want) : r; });
    const inPaths = wavs.map((_, i) => `/in${i + 1}.wav`);
    const inputs = { ...brkInputs };
    wavs.forEach((w, i) => { inputs[inPaths[i]] = w; });
    if (staticData != null) inputs['/data.txt'] = new TextEncoder().encode(staticData);
    const mapped = args.flatMap((a) =>
      a === '$INS' ? inPaths : a === '$OUT' ? ['/out.wav'] : a === '$DATA' ? ['/data.txt'] : [a]);
    const res = await cdp.run(effect.program, mapped, { inputs, outputs: ['/out.wav'] });
    const out = res.outputs['/out.wav'];
    if (!out) throw new Error(`${effect.program} produced no output (exit ${res.exitCode}).\n${res.stderr || res.stdout}`.trim());
    return out;
  }

  // Multi-output programs (cantor, isolate, partition, ...) write a *generic*
  // outfile stem and produce several numbered files, so '$OUT' maps to the stem
  // '/out' and the results are collected by prefix. Spectral ones emit numbered
  // .ana files that are each resynthesised to WAV. Returns { outputs, names }.
  if (effect.multiOut) {
    const spectral = effect.domain === 'spectral';
    const src = effect.input ? conformChannels(srcWav, effect.input) : srcWav;
    const inBytes = spectral ? await analyse(cdp, conformChannels(src, 'mono')) : src;
    const inPath = spectral ? '/in.ana' : '/in.wav';
    const ext = spectral ? 'ana' : 'wav';
    const mapped = args.map((a) =>
      a === '$IN' ? inPath : a === '$OUT' ? '/out' : a === '$DATA' ? '/data.txt' : a);
    const inputs = { [inPath]: inBytes, ...brkInputs };
    // The '$DATA' text file is either generated from params (`data`) or derived
    // from the (conformed) source (`derive`, e.g. cut times from its duration).
    const dataStr = effect.derive ? await effect.derive(cdp, src, vals) : staticData;
    if (dataStr != null) inputs['/data.txt'] = typeof dataStr === 'string' ? new TextEncoder().encode(dataStr) : dataStr;
    const res = await cdp.run(effect.program, mapped, {
      // Most multi-output programs write to the '/out' stem; programs that
      // auto-name outputs from the INPUT file (e.g. housekeep chans → in_c1,
      // in_c2, …) override the collect prefix via `effect.collect`.
      inputs, collect: [{ prefix: effect.collect || '/out', ext }],
    });
    const entries = Object.entries(res.outputs);
    if (!entries.length) throw new Error(`${effect.program} produced no output (exit ${res.exitCode}).\n${res.stderr || res.stdout}`.trim());
    const outputs = [];
    const names = [];
    for (const [path, bytes] of entries) {
      names.push(path.replace(/^\//, '').replace(/\.ana$/, '.wav'));
      outputs.push(spectral
        ? (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], bytes, { inExt: 'ana' })).bytes
        : bytes);
    }
    return { outputs, names };
  }

  if (effect.domain === 'spectral') {
    // Two-input spectral effects (morph, combine, formants vocode) analyse two
    // sounds to .ana, combine them, and resynthesise. Analysis is mono, so the
    // result is mono; `extra.in2` is the second source (defaults to the first).
    if (effect.inputs >= 2) {
      const srcRate = decodeAudio(srcWav).sampleRate;
      const in2 = conformRate(extra.in2 || srcWav, srcRate); // CDP needs matching rates
      const a1 = await analyse(cdp, conformChannels(srcWav, 'mono'));
      const a2 = await analyse(cdp, conformChannels(in2, 'mono'));
      const mapped = args.map((a) => (a === '$IN' ? '/in.ana' : a === '$IN2' ? '/in2.ana' : a === '$OUT' ? '/out.ana' : a));
      const res = await cdp.run(effect.program, mapped, {
        inputs: { '/in.ana': a1, '/in2.ana': a2, ...brkInputs }, outputs: ['/out.ana'],
      });
      const outAna = res.outputs['/out.ana'];
      if (!outAna) throw new Error(`${effect.program} produced no output (exit ${res.exitCode}).\n${res.stderr || res.stdout}`.trim());
      return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], outAna, { inExt: 'ana' })).bytes;
    }
    const pipe = async (mono) => {
      const ana = await cdp.process('pvoc', ['anal', '1', '$IN', '$OUT'], mono, { outExt: 'ana' });
      const out = await cdp.process(effect.program, args, ana.bytes, { inExt: 'ana', outExt: 'ana', data: staticData, extraInputs: brkInputs });
      return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], out.bytes, { inExt: 'ana' })).bytes;
    };
    return decodeAudio(srcWav).numChannels > 1 ? cdp.eachChannel(srcWav, pipe) : pipe(srcWav);
  }

  // Two sound (time-domain) inputs, e.g. submix.merge: stage both and mix.
  if (effect.inputs >= 2) {
    const src1 = effect.input ? conformChannels(srcWav, effect.input) : srcWav; // e.g. interleave needs mono on BOTH inputs
    let in2 = conformRate(extra.in2 || srcWav, decodeAudio(srcWav).sampleRate); // CDP needs matching rates
    if (effect.in2) in2 = conformChannels(in2, effect.in2); // e.g. subtract requires a mono 2nd input
    const mapped = args.map((a) => (a === '$IN' ? '/in.wav' : a === '$IN2' ? '/in2.wav' : a === '$OUT' ? '/out.wav' : a));
    const res = await cdp.run(effect.program, mapped, {
      inputs: { '/in.wav': src1, '/in2.wav': in2, ...brkInputs }, outputs: ['/out.wav'],
    });
    const out = res.outputs['/out.wav'];
    if (!out) throw new Error(`${effect.program} produced no output (exit ${res.exitCode}).\n${res.stderr || res.stdout}`.trim());
    return out;
  }

  // Spatialisation / fixed-input effects: conform the source to the required
  // channel layout (the program decides the output layout), no per-channel split.
  if (effect.input) {
    const conformed = conformChannels(srcWav, effect.input);
    const data = effect.derive ? await effect.derive(cdp, conformed, vals) : staticData;
    const res = await cdp.process(effect.program, args, conformed, { data, extraInputs: brkInputs });
    return res.bytes;
  }

  const data = effect.derive ? await effect.derive(cdp, srcWav, vals) : staticData;
  const res = await cdp.process(effect.program, args, srcWav, { channels: effect.mono ? 'split' : undefined, data, extraInputs: brkInputs });
  return res.bytes;
}

/** Analyse a mono WAV to a PVOCEX .ana byte array. */
async function analyse(cdp, monoWav) {
  return (await cdp.process('pvoc', ['anal', '1', '$IN', '$OUT'], monoWav, { outExt: 'ana' })).bytes;
}

/**
 * `pitch octmove`/`altharms` operate on a spectral file but also need a *binary*
 * pitchfile derived from the same input (`repitch getpitch 1` → .frq). Chain:
 *   pvoc anal → repitch getpitch (.frq) → pitch <mode> → pvoc synth (mono).
 * `modeArgs` is the `pitch` argument list with `$ANA`/`$PFRQ`/`$OUT` placeholders.
 * Falls back to the analysis round-trip when the source has no detectable pitch.
 */
async function pitchFromAnalysis(cdp, srcWav, modeArgs) {
  const ana = await analyse(cdp, conformChannels(srcWav, 'mono'));
  try {
    const gp = await cdp.run('repitch', ['getpitch', '1', '/a.ana', '/pt.wav', '/p.frq'],
      { inputs: { '/a.ana': ana }, outputs: ['/p.frq'] });
    if (!gp.outputs['/p.frq']) throw new Error('no pitch detected');
    const args = modeArgs.map((a) => (a === '$ANA' ? '/a.ana' : a === '$PFRQ' ? '/p.frq' : a === '$OUT' ? '/o.ana' : a));
    const r = await cdp.run('pitch', args, { inputs: { '/a.ana': ana, '/p.frq': gp.outputs['/p.frq'] }, outputs: ['/o.ana'] });
    if (!r.outputs['/o.ana']) throw new Error(`pitch produced no output (exit ${r.exitCode})`);
    return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], r.outputs['/o.ana'], { inExt: 'ana' })).bytes;
  } catch {
    return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], ana, { inExt: 'ana' })).bytes;
  }
}

/** Major-scale MIDI pitches over one octave from a root (CDP `-o` repeats them in all octaves). */
function majorScale(root) {
  return [0, 2, 4, 5, 7, 9, 11].map((i) => root + i).join('\n') + '\n';
}

/**
 * Pitch-data effects: extract the source's pitch contour, transform it, and
 * re-apply it to the audio as a (formant-preserving) transposition. The chain is
 *   pvoc anal -> repitch getpitch (.frq) -> repitch <mod> (.trn) -> repitch transposef -> pvoc synth
 * `mod.args(values)` is the middle step (quantise/smooth/invert) producing the
 * transposition file; `mod.qset` optionally supplies its scale data file.
 * If the source has no detectable pitch, falls back to the analysis round-trip.
 */
async function pitchDataPipeline(cdp, srcWav, values, mod) {
  const ana = await analyse(cdp, conformChannels(srcWav, 'mono'));
  try {
    const gp = await cdp.run('repitch', ['getpitch', '1', '/a.ana', '/pt.wav', '/p.frq'],
      { inputs: { '/a.ana': ana }, outputs: ['/p.frq'] });
    if (!gp.outputs['/p.frq']) throw new Error('no pitch detected');
    const inputs = { '/p.frq': gp.outputs['/p.frq'] };
    if (mod.qset) inputs['/q.txt'] = new TextEncoder().encode(mod.qset(values));
    const md = await cdp.run('repitch', mod.args(values), { inputs, outputs: ['/t.trn'] });
    if (!md.outputs['/t.trn']) throw new Error('no transposition produced');
    const tf = await cdp.run('repitch', ['transposef', '4', '/a.ana', '/t.trn', '/o.ana', '-p8'],
      { inputs: { '/a.ana': ana, '/t.trn': md.outputs['/t.trn'] }, outputs: ['/o.ana'] });
    if (!tf.outputs['/o.ana']) throw new Error('transposef failed');
    return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], tf.outputs['/o.ana'], { inExt: 'ana' })).bytes;
  } catch {
    // No clearly-pitched material to work on: return the unmodified round-trip.
    return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], ana, { inExt: 'ana' })).bytes;
  }
}

/** Mix down / up so a WAV has the channel count an effect expects ('mono'|'stereo'). */
export function conformChannels(wav, want) {
  const d = decodeAudio(wav);
  if (want === 'mono') {
    if (d.numChannels === 1) return wav;
    const mono = new Float32Array(d.length);
    for (let c = 0; c < d.numChannels; c++) for (let i = 0; i < d.length; i++) mono[i] += d.channelData[c][i] / d.numChannels;
    return encodeWav({ sampleRate: d.sampleRate, channelData: [mono] });
  }
  if (want === 'stereo') {
    if (d.numChannels === 2) return wav;
    const L = d.channelData[0];
    const R = d.numChannels > 1 ? d.channelData[1] : d.channelData[0].slice();
    return encodeWav({ sampleRate: d.sampleRate, channelData: [L, R] });
  }
  return wav;
}

/**
 * Resample a WAV to a target sample rate (linear interpolation) if it differs.
 * Used to match a second source to the first for two-input effects, since CDP's
 * morph/combine/formants/submix reject inputs whose sample rates don't match.
 */
export function conformRate(wav, targetRate) {
  const d = decodeAudio(wav);
  if (d.sampleRate === targetRate) return wav;
  const ratio = targetRate / d.sampleRate;
  const newLen = Math.max(1, Math.round(d.length * ratio));
  const channelData = d.channelData.map((ch) => {
    const out = new Float32Array(newLen);
    for (let i = 0; i < newLen; i++) {
      const pos = i / ratio;
      const i0 = Math.floor(pos);
      const a = ch[i0] || 0;
      const b = i0 + 1 < ch.length ? ch[i0 + 1] : a;
      out[i] = a + (b - a) * (pos - i0);
    }
    return out;
  });
  return encodeWav({ sampleRate: targetRate, channelData });
}
